import { MakeLogicType, actions, connect, kea, key, path, props, reducers, selectors } from 'kea'

import type { FrameId, FrameScene, FrameType } from '../../types'
import { liveSceneLabel, otherSceneIsLive } from '../../utils/systemScenes'
import { frameLogic } from '../frame/frameLogic'
import { controlLogic } from '../frame/panels/Scenes/controlLogic'

export interface SceneLivePreviewLogicProps {
  frameId: FrameId
  sceneId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sceneLivePreviewLogicValues {
  reportedSceneId: string // controlLogic
  uploadedScenes: FrameScene[] // controlLogic
  frame: FrameType // frameLogic
  scenes: FrameScene[] // frameLogic
  liveSceneId: string | null
  liveSceneName: string | null
  otherSceneLive: boolean
  otherSceneObscured: boolean
  revealedLiveSceneId: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sceneLivePreviewLogicActions {
  showLiveSceneAnyway: (liveSceneId: string) => {
    liveSceneId: string
  }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sceneLivePreviewLogicMeta {
  key: string
  __keaTypeGenInternalSelectorTypes: {
    liveSceneId: (reportedSceneId: string, frame: FrameType) => string | null
    otherSceneLive: (liveSceneId: string | null, sceneId: string) => boolean
    otherSceneObscured: (
      otherSceneLive: boolean,
      liveSceneId: string | null,
      revealedLiveSceneId: string | null
    ) => boolean
    liveSceneName: (liveSceneId: string | null, scenes: FrameScene[], uploadedScenes: FrameScene[]) => string | null
  }
}

export type sceneLivePreviewLogicType = MakeLogicType<
  sceneLivePreviewLogicValues,
  sceneLivePreviewLogicActions,
  SceneLivePreviewLogicProps
> &
  sceneLivePreviewLogicMeta

/**
 * The frame's live picture inside the scene editor's Preview panel. The
 * picture is whatever the panel shows, which is often not the scene being
 * edited; this logic knows when, so the panel can dim it and say so.
 */
export const sceneLivePreviewLogic = kea<sceneLivePreviewLogicType>([
  path(['src', 'scenes', 'workspace', 'sceneLivePreviewLogic']),
  props({} as SceneLivePreviewLogicProps),
  key((props) => `${props.frameId}:${props.sceneId}`),
  connect(({ frameId }: SceneLivePreviewLogicProps) => ({
    values: [
      controlLogic({ frameId }),
      ['sceneId as reportedSceneId', 'uploadedScenes'],
      frameLogic({ frameId }),
      ['frame', 'scenes'],
    ],
  })),
  actions({
    showLiveSceneAnyway: (liveSceneId: string) => ({ liveSceneId }),
  }),
  reducers({
    // Remembers WHICH live scene was revealed, not just "revealed": when the
    // frame moves on to yet another scene, the notice comes back.
    revealedLiveSceneId: [
      null as string | null,
      {
        showLiveSceneAnyway: (_, { liveSceneId }) => liveSceneId,
      },
    ],
  }),
  selectors({
    // The state record is the frame's own answer; the frame row carries the
    // last one it gave, which is all there is until /states responds.
    liveSceneId: [
      (s) => [s.reportedSceneId, s.frame],
      (
        reportedSceneId: sceneLivePreviewLogicValues['reportedSceneId'],
        frame: sceneLivePreviewLogicValues['frame']
      ): string | null => reportedSceneId || frame?.active_scene_id || null,
    ],
    otherSceneLive: [
      (s, p) => [s.liveSceneId, p.sceneId],
      (liveSceneId: sceneLivePreviewLogicValues['liveSceneId'], sceneId: string): boolean =>
        otherSceneIsLive(liveSceneId, sceneId),
    ],
    otherSceneObscured: [
      (s) => [s.otherSceneLive, s.liveSceneId, s.revealedLiveSceneId],
      (
        otherSceneLive: sceneLivePreviewLogicValues['otherSceneLive'],
        liveSceneId: sceneLivePreviewLogicValues['liveSceneId'],
        revealedLiveSceneId: sceneLivePreviewLogicValues['revealedLiveSceneId']
      ): boolean => otherSceneLive && revealedLiveSceneId !== liveSceneId,
    ],
    liveSceneName: [
      (s) => [s.liveSceneId, s.scenes, s.uploadedScenes],
      (
        liveSceneId: sceneLivePreviewLogicValues['liveSceneId'],
        scenes: sceneLivePreviewLogicValues['scenes'],
        uploadedScenes: sceneLivePreviewLogicValues['uploadedScenes']
      ): string | null => liveSceneLabel(liveSceneId, [...(scenes ?? []), ...(uploadedScenes ?? [])]),
    ],
  }),
])
